{'agent_id': 'target_definition_agent', 'agent_name': '目标值定义专家', 'agent_description': '专注于新能源汽车整车目标值（VTS/SSTS）自动定义的流程编排 Agent，可按车型执行完整的目标值定义流程（专业检测→映射确定→法规校核→初版定义→达标验证→参数优化→总结报告）', 'routing_keywords': ['目标值定义', '目标值设定', '定义目标值', '设定目标值', 'VTS目标', 'SSTS目标', '整车目标值定义', '目标值流程', '目标值自动定义']}
{'agent_id': 'aero_expert_agent', 'agent_name': '汽车空气动力学专家', 'agent_description': '专注于汽车空气动力学专业知识输出，可查询专业知识库、知识图谱和设计规则', 'routing_keywords': ['空气动力学', '风阻', 'Cd', '气动阻力', '升力', '边界层', '湍流', '风洞', 'CFD', '气动优化', '风噪声', '外部污染物']}
{'agent_id': 'pe_expert_agent', 'agent_name': '动力经济性专家', 'agent_description': '专注于汽车动力性和经济性专业知识输出，可查询专业知识库、知识图谱和设计规则', 'routing_keywords': ['动力性', '经济性', '加速', '最高车速', '爬坡', '能耗', '续航', '能量回收', '滚阻', '电机效率', '电池', '功率', '扭矩', '附着极限', '动力匹配', '能耗优化', '续驶里程', '百公里加速', '动力性能']}
{'agent_id': 'vts_ssts_agent', 'agent_name': 'VTS 状态分析专家', 'agent_description': '专注于新能源汽车 VTS（整车目标值）指标状态与达标判断分析，可按照不同车型、不同性能指标进行达标状态分析；进而提供VTS指标相关性分析', 'routing_keywords': ['VTS', 'vts', '达标', '达标率', '不达标', '整车目标', '整车目标值', 'VTS结果']}
{'agent_id': 'economy_agent', 'agent_name': '经济性计算工程师', 'agent_description': '专注于新能源汽车经济性（能耗、续航、阻力构成、工况对比）的计算与参数影响分析。包含空气动力学计算模块（风阻系数Cd_wt综合计算），负责空气动力学专业的校核计算和参数优化。内部的modify_economy_ssts_and_recalculate工具，是修改经济性相关SSTS参数的唯一入口。', 'routing_keywords': ['经济性', '经济性计算', '能耗', '电耗', '百公里电耗', '百公里能耗', '续航', '续驶里程', '续航里程', '油耗', '阻力', '行驶阻力', '滚阻', '风阻', '驾驶循环']}
{'agent_id': 'power_agent', 'agent_name': '动力性计算工程师', 'agent_description': '专注于新能源汽车动力性（加速性能、最高车速、爬坡能力）的计算与参数影响分析', 'routing_keywords': ['动力性', '动力', '加速', '加速度', '加速时间', '百公里加速', '0-100', '0-100km/h', '最高车速', '最高速度', '最高时速', '爬坡', '爬坡性能', '爬坡度', '最大爬坡度', '驱动力', '动力性计算', '动力性分析', 'Acceleration', 'Top Speed', 'Gradeability']}

